from __future__ import annotations

import logging

from rasa.shared.providers._litellm_sagemaker_patch import (
    install_sagemaker_event_stream_patch,
)

_litellm_configured = False


def configure_litellm_for_rasa() -> None:
    """Configures LiteLLM for use within Rasa.

    Suppresses print()-based debug footers (for example, provider-list hints) by
    setting ``litellm.suppress_debug_info`` to ``True``, sets the ``LiteLLM``
    logger level to ``WARNING``, and installs the ENG-3400 SageMaker
    event-stream decoder fix (see ``_litellm_sagemaker_patch``). Idempotent:
    only the first call applies these settings.
    """
    global _litellm_configured
    if _litellm_configured:
        return

    import litellm

    litellm.suppress_debug_info = True
    logging.getLogger("LiteLLM").setLevel(logging.WARNING)
    install_sagemaker_event_stream_patch()
    _litellm_configured = True
